node -e "
const fs=require('fs');
function walk(d){let r=[];for(const f of fs.readdirSync(d)){const p=d+'/'+f;if(fs.statSync(p).isDirectory())r=r.concat(walk(p));else if(f.endsWith('.vue'))r.push(p);}return r;}
for(const p of walk('.')){
  const s=fs.readFileSync(p,'utf8');
  const hits=[];
  if(/font-family/.test(s))hits.push('font-family');
  if(/Plus Jakarta|JetBrains/.test(s))hits.push('customfont');
  if(/fonts.googleapis/.test(s))hits.push('googlefonts');
  const mono=(s.match(/font-mono/g)||[]).length;
  const sans=(s.match(/font-sans/g)||[]).length;
  if(hits.length||mono||sans) console.log(p, 'hits:',hits.join(','),'font-mono:',mono,'font-sans:',sans);
}
"

