  .mm-dashboard.mmd-screen{ height:100vh; min-height:0; overflow:hidden; }
  .mm-dashboard .mmd-main{ overflow:hidden; }
  .mm-dashboard .mmd-row1{ flex:1.45 1 0%; min-height:0 !important; }
  .mm-dashboard .mmd-row2{ flex:0.8 1 0%; min-height:0 !important; }
}

/* 字体：统一使用系统默认字体，不单独引入/使用自定义或等宽专用字体。
   把 tailwind 的 --font-sans / --font-mono 都归一到系统默认 UI 字体栈，
   使所有 font-sans / font-mono 元素（含数字、表格等）都使用系统默认字体。 */
.mm-dashboard,
.mm-dashboard *{
  --font-sans: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
  --font-mono: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Microsoft YaHei", "PingFang SC", "Hiragino Sans GB", sans-serif;
}

